const cfg  = $('Load config').first().json;
const lead = $('Pick due lead').first().json;
const cnt  = $input.first() ? $input.first().json : { invites: 0, messages: 0 };
const seq  = Array.isArray(cfg.sequence) ? cfg.sequence : JSON.parse(cfg.sequence || '[]');
const step = seq[lead.step];
if (!step) return [{ json: { done: true, complete: true, lead } }];
const isInvite = step.type === 'invite';
const used = isInvite ? cnt.invites : cnt.messages;
const cap  = isInvite ? cfg.invites_per_day : cfg.messages_per_day;
if (used >= cap) return [{ json: { done: true, capped: true } }];
const next = seq[lead.step + 1];
const minS = cfg.cooldown_min_sec, maxS = cfg.cooldown_max_sec;
return [{ json: {
  done: false,
  lead,
  isInvite,
  mode: step.mode,
  promptOrText: step.mode === 'ai' ? step.prompt : step.text,
  voice: cfg.voice,
  account_id: cfg.account_id,
  hasNext: !!next,
  nextDelayHours: next ? next.delay_hours : null,
  cooldownSec: Math.floor(minS + Math.random() * (maxS - minS)),
} }];

const r = $('Resolve step + cap gate').first().json;
const text = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text.trim() : '';
return [{ json: { ...r, text } }];

const r = $json;
const first = (r.lead.full_name || '').split(' ')[0] || '';
const text = (r.promptOrText || '').replace(/{{\s*first_name\s*}}/g, first);
return [{ json: { ...r, text } }];
